/* SAVE > USER page actions, with the message in the top bar. name: the save's or the rename's (0 or "": automatic) */
static void up_ui_named(uint32_t op, uint32_t k, const char *name)   /* 0 load, 1 erase, 2 save, 3 rename */
{
    char l[4];
    int rc;
    up_slot_label(l, k);
    if ((op < 2u || op == 3u) && !up_used(k)) {
        ui_message(up_old(k) ? "OLD FORMAT" : "EMPTY SLOT");   /* ((2.0) converted by the editor's Restore) */
        return;
    }
    if (op && (song.playing || transport_req == 1u)) {    /* (up_put refuses too) */
        ui_message(op == 1u ? "STOP TO ERASE" : op == 3u ? "STOP TO RENAME" : "STOP TO SAVE");
        return;
    }
    if (op == 0u) {
        if (!up_load(k))                                   /* ((Skiff phase 6) refused: said why) */
            ui_say("LOADED ", l);
        return;
    }
    rc = op == 1u ? up_put(k, 0) : op == 3u ? up_rename(k, name) : up_store(k, name);
    if (rc == 3)
        ui_message(op == 1u ? "ERASED UNTIL POWER OFF" : op == 3u ? "RENAMED UNTIL POWER OFF" : "SAVED UNTIL POWER OFF");
    else if (rc)
        ui_message(op == 1u ? "ERASE ERROR" : "SAVE ERROR");
    else
        ui_say(op == 1u ? "ERASED " : op == 3u ? "RENAMED " : "SAVED ", l);
    ui.force = 1;
}

/* (1.2.1, #6) SAVE > PROJECT's NEW (KNOB 3 on an empty slot): the power-on project (felucca_init: the tracks' default
 * sounds, no steps, no lists, no motion, no scenes, the default DRUM-X kit), the way a load puts one in (stopped, the
 * tracks' patterns kept first, the ISR kept out while the sequencer's state changes). The unit's CLOCK MIDI IN TUNE and
 * SAVE's slot stay; unnamed and on no slot until SAVE writes one, with nothing to lose (clean) */
static void project_new(void)
{
    uint32_t i, k;
    mom_back(0);                                  /* ((1.3) MOMENTARY: as project_load) */
    memset(drum_mute, 0, sizeof drum_mute);
    transport_stop_now();
    (void)stage_cancel();
    if (keep_all() == 1) {
        ui_way("PATTERNS FULL", WAY_PATTERNS);
        return;
    }
    transport_req = 2;
    panic_req = (1u << NTRK) - 1u;
    fm1_irq_off();
    seq_stop();
    launch_drop();
    transport_req = 0;
    memset(&motion, 0, sizeof motion);
    memset(motion_active, 0, sizeof motion_active);
    motion_base_valid = 0;
    motion_lost = 0;
    lists_clear();
    scene_forget();
    for (i = 0; i < G_COUNT; i++)
        if (i != G_SLOT && i != G_LOAD && i != G_SAVE && !unit_g_id(i))
            song.g[i] = GP[i].def;
    memcpy(dx_kit, DX_KIT_DEF, sizeof dx_kit);
    sel_set(0);
    fm1_irq_on();
    undo_clear();
    undo_depth++;                                       /* (no undo copies of these loads) */
    fm6_init();
    for (k = 0; k < NTRK; k++) {                        /* (as felucca_init; the engine switch is the ISR's, faded) */
        track_t *t = &trk[k];
        track_defaults(t);
        t->user = 0;
        set_engine_of(t, TRK_DEF[k][0]);
        apply_preset_to(t, TRK_DEF[k][1]);
        track_defaults_steps(t);
    }
    undo_depth--;
    proj_name[0] = 0;
    proj_cur = PROJ_NO_SLOT;
    project_clean();
    sync_reload = 1;
    ui.force = 1;
    ui_message("NEW PROJECT");
    memset(snd_said, 0, sizeof snd_said);
}

