/* a VU column h tall up to its foot y1: 4 px segments lit to fh px, cyan, violet, pink, gold up it (on: one colour
 * instead), the rest off; cap: the top lit one in it (a fader's cap; 0: none) */
static void ne_vu(int32_t x, int32_t y1, int32_t w, int32_t h, int32_t fh, uint16_t on, uint16_t off, uint16_t cap)
{
    const uint16_t st[4] = {T_ACCENT, NE_VIOLET, T_THEME, NE_YELLOW};
    int32_t n = h / 4, lit = (fh * n + h / 2) / h, k;
    for (k = 0; k < n; k++)
        cv_rect(x, y1 - (k + 1) * 4, w, 3, k >= lit ? off : cap && k == lit - 1 ? cap : on ? on :
                ne_ramp(st, 4, n > 1 ? k * 1000 / (n - 1) : 0));
}

static uint32_t steps_hash(const track_t *t)
{
    uint32_t h = 2166136261u, i;
    for (i = 0; i < NSTEP; i++) {
        const step_t *st = &t->step[i];
        h = (h ^ (st->note[0] + st->n * 128u + st->time * 1024u + st->flags * 4096u + st->note[1] * 65536u)) *
            16777619u;
        h = (h ^ (st->hit | (uint32_t)st->acc << 8 | (uint32_t)st->note[2] << 16 | (uint32_t)st->note[3] << 24)) * 16777619u;
        h = (h ^ (uint8_t)st->nudge) * 16777619u;   /* ((Skiff) the roll and the grid draw it) */
    }
    return h;
}

static int32_t pr_note(const step_t *st, uint32_t j)   /* the step's note j (0..3), then its lane hits (-1: none) */
{
    if (j < 4u)
        return j < st->n ? st->note[j] : -1;
    return (st->hit >> (j - 4u)) & 1u ? DRUM_LANE_NOTE[j - 4u] : -1;
}

/* a curve as ASCII art (design/mock_u5.py's): a level a character column (lv[i]: the grid line from the top, cells
 * cw x ch from (x0, y0)), joined cell by cell: _ where it holds, / or \ where it moves a line or two, _| or |_ where it
 * jumps (a saw's or a square's edge) */
static void cr_art(int32_t x0, int32_t y0, int32_t cw, int32_t ch, const uint8_t *lv, uint32_t n, uint16_t c)
{
    uint32_t i;
    for (i = 0; i + 1u < n; i++) {
        int32_t r = lv[i], r2 = lv[i + 1u], xa = x0 + (int32_t)i * cw, ya = y0 + r * ch, yb = y0 + r2 * ch;
        if (r2 - r >= 3 || r - r2 >= 3) {
            cr_stroke(xa, ya, xa + cw - 2, ya, c);
            cr_stroke(xa + cw - 2, ya, xa + cw - 2, yb, c);
        } else {
            cr_stroke(xa, ya, xa + cw, yb, c);
        }
    }
}

/* the sample at d->pos (< len), then the next position */
static inline int32_t slc_dec_next(const slc_src_t *s, slc_dec_t *d)
{
    const slc_seg_t *g = &s->seg[d->seg];
    uint32_t rel = d->pos - g->at, b, code;
    int32_t step, vd;
    if (rel >= g->n && d->seg + 1u < s->nseg) {         /* into the next zone: its data starts from 0 / 0 */
        d->seg++;
        g++;
        rel = d->pos - g->at;
        d->pred = 0;
        d->idx = 0;
    }
    b = SMP_DATA[g->off + (rel >> 1)];
    code = (rel & 1u) ? (b >> 4) : (b & 15u);
    step = IMA_STEP[d->idx];
    vd = step >> 3;
    if (code & 4u)
        vd += step;
    if (code & 2u)
        vd += step >> 1;
    if (code & 1u)
        vd += step >> 2;
    d->pred = clamp(d->pred + ((code & 8u) ? -vd : vd), -32768, 32767);
    d->idx = clamp(d->idx + IMA_IDX[code & 7u], 0, 88);
    d->pos++;
    return d->pred;
}

/* the bar level 0..8 of partial k: the registration plus SUB / BODY / TOP */
static int32_t drw_level(const int16_t *p, uint32_t k)
{
    int32_t d = DRW_REG[(uint32_t)p[P_E0] & 15u][k] - '0';
    d += k < 2u ? p[P_E1] : k < 4u ? p[P_E2] : p[P_E3];
    return clamp(d, 0, 8);
}

/* the carriers of algorithm a: bit k operator k + 1 (fm6_carriers counts the sixth first) */
static uint32_t fm6_car_ops(uint32_t a)
{
    uint32_t c = fm6_carriers(a), r = 0, k;
    for (k = 0; k < 6u; k++)
        r |= (c >> (5u - k) & 1u) << k;
    return r;
}

