static void analog_note_on(track_t *t, voice_t *v)
{
    (void)t;
    v->ph[1] = v->ph[0] + 0x40000000u;
    v->s[0] = v->s[1] = 0;                            /* filter */
    if (!v->s[2])
        v->s[2] = 0x1234567 + (int32_t)v->age;        /* noise state */
    v->s[3] = 0;                                      /* SYNC: no restart pending */
}

/* (#41) pd_one, and with b->old the old bend's wave fading into this one's over the block (i: the sample in it), as the
 * amplitude ramps: a bend switched at the block's start steps the wave there, a click each block while ENV -> DCW moves
 * it fast (an attack, a release; PD BRASS's low notes). The old bend has no old: one level */
static int32_t pd_wave(const pd_t *b, uint32_t ph, uint32_t i)
{
    int32_t s = pd_one(b, ph), s0;
    if (!b->old)
        return s;
    s0 = pd_wave(b->old, ph, i);
    return s0 + ((s - s0) * (int32_t)(i + 1u) >> CTL_LOG2);
}

static void phase_render(track_t *t, voice_t *v, int32_t *out, uint32_t n, const vmod_t *m)
{
    if (t->p[P_E7] > 0) {
        if (v->s[4] == PD_UNFOLDED)
            phase_xfade(t, v, out, n, m, 1);
        else
            phase_render_f(t, v, out, n, m);
    } else if (v->s[4] != PD_UNFOLDED) {
        phase_xfade(t, v, out, n, m, 0);
    } else {
        phase_loop(t, v, out, n, m, 0);
    }
}

static void grain_note_on(track_t *t, voice_t *v)
{
    gr_part_t *P = (gr_part_t *)eng_part(t);   /* (Skiff: the part's shared area, engines.c) */
    uint32_t vi = (uint32_t)(v - t->v) % NVOICE, i;
    if (grain_off(t))
        return;
    v->s[0] = gr_find((uint32_t)t->p[P_E0] % SMP_NALL, v->note);
    v->s[1] = 0;                                    /* the first grain at once */
    v->ph[0] = 0;                                   /* (the sine's phase: no data) */
    if (!v->env) {                                  /* a fresh voice: no grains left from before */
        for (i = 0; i < GR_NG; i++)
            if (P->g[i].owner == vi + 1u)
                P->g[i].owner = 0;
        v->s[2] = 0;
    }
}

/* reverse: decode [hi - GR_RB + 1, hi] into the grain's window */
static void gr_fill(const gr_part_t *P, gr_grain_t *g, int16_t *rb, uint32_t zl, uint32_t hi)
{
    uint32_t lo = hi >= GR_RB - 1u ? hi - (GR_RB - 1u) : 0u, q;
    int32_t pred, idx;
    gr_seek(P, g->z, zl, lo, &pred, &idx);
    for (q = lo; q <= hi; q++)
        rb[q - lo] = (int16_t)gr_dec(g->z, q, &pred, &idx);
    g->rlo = lo;
}

static phys_slot_t *phys_slot_of(track_t *t, voice_t *v)
{
    uint32_t i;
    if (t < &trk[0] || t >= &trk[NHEAVY])               /* ((Skiff phase 6) a light track: no PHYS state, silent) */
        return 0;
    i = (uint32_t)(v - t->v);
    return i < PHYS_POLY ? &((phys_slot_t *)eng_part(t))[i] : 0;   /* (Skiff: the part's shared area, engines.c) */
}

/* the exciter of n samples into aux (Q20): Dust, or the burst through the Svf low-pass */
static void px_string_excite(const px_string_blk_t *B, px_string_t *S, int32_t *aux, uint32_t n)
{
    uint32_t i, bk = S->bk, bend = S->bn + S->bd;
    px_csvf_st_t ex = S->ex;
    for (i = 0; i < n; i++) {
        int32_t in = 0, x = 0;
        if (B->dust_thr) {
            uint32_t u = px_rand(&S->rng);
            if (u < B->dust_thr)
                x = (int32_t)(((((uint64_t)u * B->dust_inv) >> 32) * (uint32_t)B->dust_gain) >> 11);   /* Q20 */
        } else if (bk < bend) {                          /* rand in -1..1; with a pluck position, the */
            if (bk < S->bn)                              /* half of it minus its half pos / 2 periods */
                x = (int32_t)(px_rand(&S->nz_a) >> (S->bd ? 12 : 11)) - (S->bd ? 1 << 19 : 1 << 20);   /* later */
            if (S->bd && bk >= S->bd)
                x -= (int32_t)(px_rand(&S->nz_b) >> 12) - (1 << 19);
            bk++;
        }
        if (x || ex.low || ex.band) {
            int32_t l0;
            px_csvf_pass(&S->exc, &ex, x);
            l0 = ex.low;
            px_csvf_pass(&S->exc, &ex, x);
            in = (l0 + ex.low) >> 1;
            ex.band = px_clamp(ex.band, -(5 << 20), 5 << 20);   /* stays far below (DaisySP's +-1 burst: */
            ex.low = px_clamp(ex.low, -(16 << 20), 16 << 20);   /* ~1.3); bounded all the same */
            if (!x && ex.low > -16 && ex.low < 16 && ex.band > -16 && ex.band < 16)
                ex.low = ex.band = 0;                    /* rung out */
        }
        aux[i] = in - (B->dust_thr ? B->dust_dc : 0);   /* (the string has its own DC blocker) */
    }
    S->bk = bk;
    S->ex = ex;
}

static void fm6_block(track_t *t)       /* once a block and part: the macros, the LFO */
{
    uint32_t tr = (uint32_t)(t - trk);
    if (tr >= NTRK)
        return;
    fm6_sync(t);
    fm6_lfo_v[tr] = fm6_lfo_sample(&fm6_lfo[tr]);
    fm6_lfo_d[tr] = fm6_lfo_delay(&fm6_lfo[tr]);
}

/* KNOB k (0..3) turned s: the window's value; a switch one a detent */
static void dx_knob(uint32_t k, int32_t s)
{
    uint32_t l = dx_ui_lane & 7u, w = dx_ui_win % DX_NWIN, i = DX_WIN[w][k & 3u][1];
    dx_lane_t *L = &dx_kit[l];
    int32_t d = s > 0 ? 1 : -1;
    switch (DX_WIN[w][k & 3u][0]) {
    case DXK_A:
    case DXK_B: {
        uint8_t *v = DX_WIN[w][k & 3u][0] == DXK_A ? L->a : L->b;
        v[i] = (uint8_t)clamp(v[i] + accel(EN_K1 + k, s, 127), 0, 127);
        break;
    }
    case DXK_LEVEL: {                                   /* (as any knob: its automation too) */
        const param_desc_t *pd = &TP[P_LN0 + l];
        int16_t *vp = &TSEL->p[P_LN0 + l];
        *vp = (int16_t)param_turn(pd, *vp, accel(EN_K1 + k, s, pd->max - pd->min));
        motion_capture(TSEL, P_LN0 + l, *vp);
        break;
    }
    case DXK_DRV:
        L->mode = (uint8_t)(s > 0 ? L->mode | DX_DRIVE : L->mode & ~DX_DRIVE);
        break;
    case DXK_WAVE:
        L->mode = (uint8_t)((L->mode & ~3u) | (uint32_t)clamp((int32_t)(L->mode & 3u) + d, 0, 3));
        break;
    case DXK_FILT:
        L->mode = (uint8_t)((L->mode & ~0x0Cu) | (uint32_t)clamp((int32_t)((L->mode >> 2) & 3u) + d, 0, DXF_HP) << 2);
        break;
    case DXK_SNAP:
        L->mode = (uint8_t)(s > 0 ? L->mode | 0x10u : L->mode & ~0x10u);
        break;
    default:                                            /* PSHP */
        L->mode = (uint8_t)((L->mode & ~0x60u) | (uint32_t)clamp((int32_t)((L->mode >> 5) & 3u) + d, 0, 3) << 5);
        break;
    }
}
